def _safe_stat(value):
    """Return a finite shape statistic, using zero when it is undefined."""
    if value is None or not np.isfinite(value):
        return 0.0
    return float(value)


def _summary_features(alpha, beta):
    """Return [mu_a, sigma_a, skew_a, kurt_a, mu_b, sigma_b, skew_b, kurt_b]."""
    with warnings.catch_warnings():
        # Constant configurations have undefined skewness/kurtosis. They are
        # converted to zero below, so SciPy's precision-loss warning is noise.
        warnings.simplefilter("ignore", RuntimeWarning)
        skew_alpha = _safe_stat(stats.skew(alpha, bias=False))
        kurt_alpha = _safe_stat(stats.kurtosis(alpha, bias=False))
        skew_beta = _safe_stat(stats.skew(beta, bias=False))
        kurt_beta = _safe_stat(stats.kurtosis(beta, bias=False))

    return [
        np.mean(alpha).item(),
        np.var(alpha).item()**0.5,
        skew_alpha,
        kurt_alpha,
        np.mean(beta).item(),
        np.var(beta).item()**0.5,
        skew_beta,
        kurt_beta,
    ]


def _normalize_summary_features(data_x):
    """Normalize eight summary features without changing legacy moment scaling."""
    data_x = np.asarray(data_x, dtype=float)
    moment_columns = [0, 1, 4, 5]
    shape_columns = [2, 3, 6, 7]

    moment_values = data_x[:, moment_columns]
    moment_range = np.max(moment_values) - np.min(moment_values)
    if moment_range == 0:
        moment_range = 1.0
    data_x[:, moment_columns] /= moment_range

    # Skewness and kurtosis are dimensionless and may have different ranges.
    # Scale each one to at most unit magnitude so its squared terms stay stable.
    for column in shape_columns:
        scale = np.max(np.abs(data_x[:, column]))
        if scale != 0:
            data_x[:, column] /= scale

    return data_x, 1/moment_range


# read script 
def findtheline(file):
    file1 = open(file, 'r')
    Lines = file1.readlines()

    out = '['
    flag = False
    counter = 0
    findline = False
    for line in Lines:
        if line.find("'ls_ipc': ") != -1:
            findline = True
        if findline == True:
            if line.find("'ls_ipc': [") != -1:
                a_0 = line.find("'ls_ipc': ") + len("'ls_ipc': ")
                a_1 = line.find(", 'N': ")  
                a_2 = line.find("'ls_it':") + len("'ls_it':")
                a_3 = line.find(", 'outer_loop': 1,")
                out += '[' + line[a_0:a_1] + ',' +  line[a_2:a_3]+','
            if line.find("all model performance: mean  =") != -1:
                a_0 = line.find("all model performance: mean  =") + len("all model performance: mean  =")
                a_1 = line.find("%  std =")
                a_2 = line.find("%  std =") + len("%  std =")
                a_3 = -2
                out += line[a_0:a_1]+ ','+ line[a_2:a_3] + '],'
        counter += 1
    out = out[:-1]
    out += ']'
    file1.close()
    return eval(out)

def read_data(file, seperate=False):
    out = findtheline(file)
    if seperate:
        if file.find('N100_1')!=-1:
            file = file.replace('N100_1','N100_2')
        elif file.find('N100_0')!=-1:
            file = file.replace('N100_0','N100_1')
        out_sepe = findtheline(file)
    else:
        out_sepe = [] 
    # preprocess the list to mean standard diviation
    out += out_sepe
    data_x = []
    data_y = []
    for x in out:
        data_x.append(_summary_features(x[0], x[1]))
        data_y.append(x[2])
    
    data_x, n_1 = _normalize_summary_features(data_x)
    return data_x, data_y, n_1

