# Define the curve fitting function
def fit_curve(x, y,select = 0, epochs=1000, lr=1e-1,at=25,end=30):
    """Fit a selected curve model.

    Existing selections 0--4 are unchanged. The moment-polynomial models are:
      5 or "A": first-order means, no variance terms
      6 or "B": first-order means, first-order variances
      7 or "C": second-order means, no variance terms
      8 or "D": second-order means, first-order variances
      9 or "E": second-order means, second-order variances
     10 or "F": third-order means, second-order variances
     11 or "G": Model D plus first/second-order skewness
     12 or "H": Model G plus first/second-order kurtosis
    """
    if end <= at:
        print("Not enough test samples")
        exit(0)
    x = np.asarray(x)
    y = np.asarray(y)

    # The original selections 0--4 expect the legacy four-column layout.
    # Preserve their behavior when read_data/test_read returns eight columns.
    if select in (0, 1, 2, 3, 4) and x.ndim == 2 and x.shape[1] >= 8:
        x = x[:, [0, 1, 4, 5]]

    x_train = x[:at]
    y_train = y[:at]
    x_eval = x[at:end]
    y_eval = y[at:end]
    if select == 0:
        # select = 0, epochs=2000, lr=1e-1
        print("You are selecting Quandratic Curve")
        
        a, b, c, d, e, f = 0.001, 0.001, 0.001, -0.01, 0.0001, -0.01
    
        for i in range(epochs):
            y_fitted = model_quandra(x_train, a, b, c, d, e, f)
            # loss is half error square
            error = y_fitted-y_train
            da = sum(error)/len(error)
            db = np.dot(error, x_train[:,0])/len(error)
            dc = np.dot(error,(x_train[:,0]**2 + x_train[:,1]**2))/len(error)
            # dc += error*x_train[j][0]**2
            dd = np.dot(error,x_train[:,2])/len(error)
            de = np.dot(error,(x_train[:,2]**2 + x_train[:,3]**2))/len(error)
            df = np.dot(error,x_train[:,0]*x_train[:,2])/len(error)
            
            a -= lr*da
            b -= lr*db
            c -= lr*dc
            d -= lr*dd
            e -= lr*de
            f -= lr*df

            y_fitted = model_quandra(x_eval, a, b, c, d, e, f)
            error_abs = np.mean(np.abs(y_fitted-y_eval))
            error_mse = np.mean((y_fitted-y_eval)**2)
            error_mape = np.mean(np.abs((y_fitted- y_eval)/y_eval))*100
            error_nrmse = np.sqrt(np.mean((y_fitted-y_eval)**2))/(np.max(y_eval)-np.min(y_eval))
            print("Eval {}: Abs {:.2f},MSE {:.2f},MAPE {:.2f},NRMSE {:.2f}".format(i, error_abs,error_mse, error_mape,error_nrmse))
        print("{}, {}, {}, {}, {}, {}".format(a,b,c,d,e,f))

    elif select == 1:
        print("You are selecting Linear Curve")
        
        a, b, c, d, e = 0.001, 0.001, 0.001, 0.001, 0.001
    
        for i in range(epochs):
            y_fitted = model_linear(x_train, a, b, c, d, e)
            
            error = y_fitted-y_train
            da = sum(error)/len(error)
            db = np.dot(error, x_train[:,0])/len(error)
            dc = np.dot(error, x_train[:,1])/len(error)
            dd = np.dot(error, x_train[:,2])/len(error)
            de = np.dot(error, x_train[:,3])/len(error)
            
            a -= lr*da
            b -= lr*db
            c -= lr*dc
            d -= lr*dd
            e -= lr*de

            error = np.sum(np.abs(y_fitted-y_train))/len(y_fitted)    

            # print("Iteration {}: MSE {}".format(i, error))

            y_fitted = model_linear(x_eval, a, b, c, d, e)
            error_abs = np.mean(np.abs(y_fitted-y_eval))
            error_mse = np.mean((y_fitted-y_eval)**2)
            error_mape = np.mean(np.abs((y_fitted- y_eval)/y_eval))*100
            error_nrmse = np.sqrt(np.mean((y_fitted-y_eval)**2))/(np.max(y_eval)-np.min(y_eval))
            print("Eval {}: Abs {:.2f},MSE {:.2f},MAPE {:.2f},NRMSE {:.2f}".format(i, error_abs,error_mse, error_mape,error_nrmse))

    elif select == 2:
        print("You are selecting Multivariant Polynomial Curve")
        
        a, b, c, d, e, f, g, h, i= 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001
    
        for j in range(epochs):
            y_fitted = model_Multivariate_polynomial(x_train, a, b, c, d, e, f, g, h, i)
            error = y_fitted-y_train

            da = np.dot(error, x_train[:,0]**2)/len(error)
            db = np.dot(error, x_train[:,1]**2)/len(error)
            dc = np.dot(error, x_train[:,2]**2)/len(error)
            dd = np.dot(error, x_train[:,3]**2)/len(error)
            de = np.dot(error, x_train[:,0])/len(error)
            df = np.dot(error, x_train[:,1])/len(error)
            dg = np.dot(error, x_train[:,2])/len(error)
            dh = np.dot(error, x_train[:,3])/len(error)
            di = sum(error)/len(error)
            
            a -= lr*da
            b -= lr*db
            c -= lr*dc
            d -= lr*dd
            e -= lr*de
            f -= lr*df
            g -= lr*dg
            h -= lr*dh
            i -= lr*di

            error = np.sum(np.abs(y_fitted-y_train))/len(y_fitted)    

            # print("Iteration {}: MSE {}".format(j, error))

            y_fitted = model_Multivariate_polynomial(x_eval, a, b, c, d, e, f, g, h, i)
            error_abs = np.mean(np.abs(y_fitted-y_eval))
            error_mse = np.mean((y_fitted-y_eval)**2)
            error_mape = np.mean(np.abs((y_fitted- y_eval)/y_eval))*100
            error_nrmse = np.sqrt(np.mean((y_fitted-y_eval)**2))/(np.max(y_eval)-np.min(y_eval))
            print("Eval {}: Abs {:.2f},MSE {:.2f},MAPE {:.2f},NRMSE {:.2f}".format(i, error_abs,error_mse, error_mape,error_nrmse))

    elif select == 3:
        print("You are selecting Multivariant Logistic Curve")
        a, b, c, d, e, f = 0.001, 0.001, 0.001, 0.001, 0.001, 0.001
    
        for i in range(epochs):
            y_fitted = model_Multivariante_logistic(x_train, a, b, c, d, e, f)
            
            error = y_fitted-y_train
            delta = 1/(1+np.exp(-(a*x_train[:,0] +b*x_train[:,1] +c*x_train[:,2] +d*x_train[:,3] +e)))
            da = np.dot(error, f*delta*(1-delta)*x_train[:,0])/len(error)
            db = np.dot(error, f*delta*(1-delta)*x_train[:,1])/len(error)
            dc = np.dot(error, f*delta*(1-delta)*x_train[:,2])/len(error)
            dd = np.dot(error, f*delta*(1-delta)*x_train[:,3])/len(error)
            de = np.dot(error, f*delta*(1-delta))/len(error)
            df = np.dot(error,delta)/len(error)
            
            a -= lr*da
            b -= lr*db
            c -= lr*dc
            d -= lr*dd
            e -= lr*de
            f -= lr*df

            error = np.sum(np.abs(y_fitted-y_train))/len(y_fitted)    

            # print("Iteration {}: MSE {}".format(i, error))

            y_fitted = model_Multivariante_logistic(x_eval, a, b, c, d, e, f)
            error_abs = np.mean(np.abs(y_fitted-y_eval))
            error_mse = np.mean((y_fitted-y_eval)**2)
            error_mape = np.mean(np.abs((y_fitted- y_eval)/y_eval))*100
            error_nrmse = np.sqrt(np.mean((y_fitted-y_eval)**2))/(np.max(y_eval)-np.min(y_eval))
            print("Eval {}: Abs {:.2f},MSE {:.2f},MAPE {:.2f},NRMSE {:.2f}".format(i, error_abs,error_mse, error_mape,error_nrmse))

    elif select == 4:
        print("You are selecting Linear Curve")
        a, b, c, d, e, f = 0.001, 0.001, 0.001, 0.001, 0.001, 0.001
    
        for i in range(epochs):
            y_fitted = model_Multivariante_exponential(x_train, a, b, c, d, e, f)
            
            error = y_fitted-y_train
            delta = np.exp(-(a*x_train[:,0] +b*x_train[:,1] +c*x_train[:,2] +d*x_train[:,3] +e))
            da = np.dot(error, f*delta*x_train[:,0])/len(error)
            db = np.dot(error, f*delta*x_train[:,1])/len(error)
            dc = np.dot(error, f*delta*x_train[:,2])/len(error)
            dd = np.dot(error, f*delta*x_train[:,3])/len(error)
            de = np.dot(error, f*delta)/len(error)
            df = np.dot(error,(1-delta))/len(error)
            
            a -= lr*da
            b -= lr*db
            c -= lr*dc
            d -= lr*dd
            e -= lr*de
            f -= lr*df

            error = np.sum(np.abs(y_fitted-y_train))/len(y_fitted)    

            # print("Iteration {}: MSE {}".format(i, error))

            y_fitted = model_Multivariante_exponential(x_eval, a, b, c, d, e, f)
            error_abs = np.mean(np.abs(y_fitted-y_eval))
            error_mse = np.mean((y_fitted-y_eval)**2)
            error_mape = np.mean(np.abs((y_fitted- y_eval)/y_eval))*100
            error_nrmse = np.sqrt(np.mean((y_fitted-y_eval)**2))/(np.max(y_eval)-np.min(y_eval))
            print("Eval {}: Abs {:.2f},MSE {:.2f},MAPE {:.2f},NRMSE {:.2f}".format(i, error_abs,error_mse, error_mape,error_nrmse))

    elif select in (5, "A", "a"):
        print("You are selecting Model A: 1st-order means, no variance terms")
        return _fit_moment_polynomial(
            x_train, y_train, x_eval, y_eval,
            model_A_mean1_var0, "A", epochs, lr
        )

    elif select in (6, "B", "b"):
        print("You are selecting Model B: 1st-order means and variances")
        return _fit_moment_polynomial(
            x_train, y_train, x_eval, y_eval,
            model_B_mean1_var1, "B", epochs, lr
        )

    elif select in (7, "C", "c"):
        print("You are selecting Model C: 2nd-order means, no variance terms")
        return _fit_moment_polynomial(
            x_train, y_train, x_eval, y_eval,
            model_C_mean2_var0, "C", epochs, lr
        )

    elif select in (8, "D", "d"):
        print("You are selecting Model D: 2nd-order means, 1st-order variances")
        return _fit_moment_polynomial(
            x_train, y_train, x_eval, y_eval,
            model_D_mean2_var1, "D", epochs, lr
        )

    elif select in (9, "E", "e"):
        print("You are selecting Model E: 2nd-order means and variances")
        return _fit_moment_polynomial(
            x_train, y_train, x_eval, y_eval,
            model_E_mean2_var2, "E", epochs, lr
        )

    elif select in (10, "F", "f"):
        print("You are selecting Model F: 3rd-order means, 2nd-order variances")
        return _fit_moment_polynomial(
            x_train, y_train, x_eval, y_eval,
            model_F_mean3_var2, "F", epochs, lr
        )

    elif select in (11, "G", "g"):
        print("You are selecting Model G: Model D plus skewness terms")
        return _fit_moment_polynomial(
            x_train, y_train, x_eval, y_eval,
            model_G_ours_skew2, "G", epochs, lr
        )

    elif select in (12, "H", "h"):
        print("You are selecting Model H: Model G plus kurtosis terms")
        return _fit_moment_polynomial(
            x_train, y_train, x_eval, y_eval,
            model_H_ours_skew2_kurt2, "H", epochs, lr
        )

    else:
        raise ValueError(
            "Unknown select value. Use 0--4 for the original models or "
            "5--12 (equivalently A--H) for the moment-polynomial models."
        )

  
     

    
